      let outWidth = i32(uniforms.result_shape[2]);

    let coords = vec4<i32>(
      batch,
      row / outWidth,
      row % outWidth,
      col);


      value = value + getBiasByOutputCoords(coords);

      value = (f32(1.0) / (f32(1.0) + exp(-value)));
      setOutputAtCoords(coords[0], coords[1], coords[2], coords[3], value);
      }
    }

